uint8_t fatigue_rf_predict_proba_q100(const float features[FATIGUE_RF_FEATURE_COUNT])
{
    uint32_t sum_q255 = 0U;
    for (int32_t t = 0; t < FATIGUE_RF_TREE_COUNT; ++t)
    {
        int32_t base = tree_offsets[t];
        int32_t n = 0;
        while (1)
        {
            int32_t idx = base + n;
            int8_t feat = node_feature[idx];
            if (feat < 0)
            {
                sum_q255 += node_leaf_prob_q255[idx];
                break;
            }
            n = (features[(int)feat] <= node_threshold[idx]) ?
                node_left[idx] : node_right[idx];
        }
    }
    return (uint8_t)((sum_q255 * 100U + (255U * FATIGUE_RF_TREE_COUNT / 2U)) /
                     (255U * FATIGUE_RF_TREE_COUNT));
}
